WITH op AS (SELECT id FROM operators WHERE slug='bingo-auctions'),
inv AS (SELECT i.* FROM invoices i, op WHERE i.operator_id=op.id AND i.created_at >= now()-interval '84 days' AND i.status::text <> 'canceled'),
cl AS (SELECT l.* FROM lots l, op WHERE l.operator_id=op.id AND l.closed_at >= now()-interval '84 days' AND l.deleted_at IS NULL)
SELECT
(SELECT json_agg(w ORDER BY wk) FROM (SELECT date_trunc('week', created_at AT TIME ZONE 'America/Chicago')::date wk, count(*) invoices, count(DISTINCT bidder_id) buyers, sum(subtotal_cents) hammer_c, sum(buyer_premium_cents) bp_c, sum(tax_cents) tax_c, sum(total_cents) total_c, sum(coalesce(square_processing_fee_cents,0)) sq_fee_c, sum(coalesce(refunded_cash_cents,0)) refund_cash_c, sum(coalesce(credit_applied_cents,0)) credit_c FROM inv GROUP BY 1) w) weekly,
(SELECT json_build_object('closed_lots', count(*), 'sold', count(*) FILTER (WHERE winner_bidder_id IS NOT NULL), 'avg_hammer_c', round(avg(current_bid_cents) FILTER (WHERE winner_bidder_id IS NOT NULL)), 'median_hammer_c', percentile_cont(0.5) WITHIN GROUP (ORDER BY current_bid_cents) FILTER (WHERE winner_bidder_id IS NOT NULL), 'avg_msrp_sold_c', round(avg(msrp_cents) FILTER (WHERE winner_bidder_id IS NOT NULL AND msrp_cents>0)), 'relisted_children', count(*) FILTER (WHERE relisted_from_lot_id IS NOT NULL), 'auctions', count(DISTINCT auction_id), 'zero_bid', count(*) FILTER (WHERE coalesce(bid_count,0)=0)) FROM cl) lots84,
(SELECT json_build_object('buyers', count(DISTINCT bidder_id), 'buyers_2plus_weeks', (SELECT count(*) FROM (SELECT bidder_id FROM inv GROUP BY 1 HAVING count(DISTINCT date_trunc('week', created_at))>=2) z), 'relisted_unpaid', count(*) FILTER (WHERE status::text='payment_failed_relisted'), 'refunded_full', count(*) FILTER (WHERE status::text='refunded'), 'part_refund', count(*) FILTER (WHERE status::text='partially_refunded')) FROM inv) buyers84,
(SELECT json_build_object('lines', count(*), 'picked', count(il.picked_up_at), 'refunded', count(il.refunded_at), 'forfeited', count(il.forfeited_at)) FROM invoice_lots il JOIN inv ON inv.id=il.invoice_id) lines84,
(SELECT count(*) FROM bidders WHERE deleted_at IS NULL) bidders_total,
(SELECT count(*) FROM bidders WHERE deleted_at IS NULL AND square_customer_id IS NOT NULL AND card_last4 IS NOT NULL) bidders_with_card
